import icons from '@/assets/icons.svg?raw';
import templateHtml from './product.html?raw';
import stylesCss from './product.css?raw';
import themeCss from '@/external/theme.css?raw';

import { getOdometerRange, getQueryValue, $t, renderTranslations, SITE_LOCALE } from '@/utils.js';
import '@/internal/photos/photos.js';
import '@/internal/checkout/checkout.js';

const template = document.createElement('template');
template.innerHTML = `<style>${themeCss}${stylesCss}</style>${templateHtml}${icons}`;

class VehicleProduct extends HTMLElement {

  #refs = []
  #vehicle = {};

  static get observedAttributes() {
    return ['uuid'];
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === "uuid" && oldValue !== newValue) {
      const carId = this.getAttribute('uuid') || getQueryValue('uuid');
      if (carId) {
        this.#fetchVehicle(carId);
      } else {
        this.#render();
      }
    }
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.appendChild(template.content.cloneNode(true));
  }

  connectedCallback() {

    const root = this.shadowRoot
    renderTranslations(root)

    this.#refs = {
      grid: root.querySelector('.layout-grid'),
      checkout: root.querySelector("vehicle-checkout"),
      provider: root.querySelector('.card.provider'),
      provider_logo: root.querySelector('.provider-logo'),
      photos: root.querySelector('vehicle-photos'),
      equipment: root.querySelector('.equipment-grid'),
    }

    this.#setupEventListeners();

    const carId = this.getAttribute('uuid') || getQueryValue('uuid');
    if (carId) {
      this.#fetchVehicle(carId);
    } else {
      this.#render();
    }
  }

  async #fetchVehicle(carId) {
    try {
      const response = await fetch(`https://www.carify.com/public_api/vehicles/${carId}/?lang=${SITE_LOCALE}`)
      if (!response.ok) {
        throw new Error(`Failed to fetch vehicle details (Status: ${response.status})`);
      }
      const responseJson = await response.json();
      const vehicleData = responseJson.results || {};

      this.#vehicle = vehicleData

      const checkout = this.shadowRoot.querySelector('.checkout');
      checkout.setAttribute('vehicle_id', vehicleData.id)
      checkout.setAttribute('vehicle_slug', vehicleData.slug)
      checkout.setAttribute('options', JSON.stringify(vehicleData.lease_packages))

      this.#render()

    } catch (error) {
      console.error('Error loading vehicle data:', error);
      this.showError(error.message);
    }
  }

  showError(message) {
    const root = this.shadowRoot;
    const grid = root.querySelector('.layout-grid');
    if (grid) {
      grid.innerHTML = `
        <div style="grid-column: span 2; text-align: center; padding: 40px; color: #ef4444; font-weight: 600;">
          ⚠️ Unable to load vehicle: ${message}
        </div>
      `;
    }
  }

  #setupEventListeners() {
    const toggleBtn = this.shadowRoot.querySelector('#toggle-equipment-btn');
    const wrapper = this.shadowRoot.querySelector('#equipment-wrapper');
    if (toggleBtn && wrapper) {
      toggleBtn.addEventListener('click', () => {
        const isExpanded = wrapper.classList.toggle('expanded');
        toggleBtn.textContent = isExpanded ? $t('show_less') : $t('show_more')
      });
    }
  }

  #render() {
    const data = this.#vehicle;
    const root = this.shadowRoot;

    if (!data.id) {
      this.#refs.grid.classList.add('empty')
      return;
    }

    if (this.hasAttribute('show-provider')) {
      this.#refs.provider.removeAttribute('disabled')
    }

    if (this.hasAttribute('book-now')) {
      this.#refs.checkout.setAttribute("book", true)
    }

    if (this.#refs.equipment && data.equipment) {
      this.#refs.equipment.innerHTML = data.equipment
        .map(item => `<div class="equipment-item" title="${item}">${item}</div>`)
        .join('');
    }

    if (this.#refs.photos && data.images) {
      this.#refs.photos.setAttribute('images', JSON.stringify(data.images));
    }

    const setText = (selector, text) => {
      const el = root.querySelector(selector);
      if (el) el.textContent = text || '';
    };

    setText('.vehicle-main-title', data.name)
    setText('.spec-make', data.make_name);
    setText('.spec-model', data.model_name);
    setText('.spec-body', data.car_type_display);
    setText('.spec-fuel', data.fuel_type_display);
    setText('.spec-trans', data.transmission_display);
    setText('.spec-mileage', getOdometerRange(data.odometer));
    setText('.spec-drive', data.drive_type_display);
    setText('.spec-year', data.registration_date.split('-')[0]);
    setText('.spec-power', `${parseInt(data.horse_power, 10)} BHP`);
    setText('.spec-consumption', `${Number(data.fuel_consumption).toFixed(1)}L/100km`);
    setText('.spec-emissions', `${data.co2em}g/km`);
    setText('.spec-seats', `${data.no_of_seats} Seats`);
    setText('.provider-name', data.dealer_address?.name);
    setText('.provider-address', `${data.dealer_address?.street}, ${data.dealer_address?.city}`);

    this.#refs.provider_logo.setAttribute('src', data.dealer_image)
    this.#refs.provider_logo.setAttribute('alt', data.dealer_name)
  }
}

customElements.define('carify-vehicle-product', VehicleProduct);
