import { $t, SITE_LOCALE, renderTranslations } from "@/utils.js"
import filterHtml from './filter.html?raw';
import filterCss from './filter.css?raw';

const template = document.createElement('template');
template.innerHTML = `<style>${filterCss}</style>${filterHtml}`;

export class VehicleFilter extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.appendChild(template.content.cloneNode(true));

    this.activeIndex = '';
    this.isOpen = false;
    this.totalCount = 0;
    this.allCount = 0;

    // Dynamically generate the last 5 years ending with the current year (2026)
    const currentYear = new Date().getFullYear();
    const yearOpts = {};
    for (let i = 0; i < 5; i++) {
      const yr = String(currentYear - i);
      yearOpts[yr] = { label: yr, extra: null };
    }

    this.pills = {
      make: { title: $t('filter.brand'), multi: true, selected: new Map(), options: {} },
      body: { title: $t('filter.body'), multi: true, selected: new Map(), options: {} },
      gear: { title: $t('filter.transmission'), multi: true, selected: new Map(), options: {} },
      fuel: { title: $t('filter.fuel'), multi: true, selected: new Map(), options: {} },
      year: { title: 'Year', multi: true, selected: new Map(), options: yearOpts },
      price: {
        title: 'Price Range',
        multi: false,
        selected: new Map(),
        options: {
          s: { label: '≤650', extra: null },
          m: { label: '≤850', extra: null },
          l: { label: '≤1000', extra: null },
          b: { label: '>1000', extra: null }
        }
      }
    };
  }

  static get observedAttributes() {
    return ['total'];
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name == "total" && oldValue !== newValue) {
      this.#updateButtonLabel(parseInt(newValue))
    }
  }

  async connectedCallback() {

    renderTranslations(this.shadowRoot)
    await this.#fetchInitialData();

    this.#renderOptions();
    this.#setupEventListeners();
    this.#updateIndicator();
    window.addEventListener('resize', () => this.#updateIndicator());

    // Update indicator position if user scrolls pills horizontally
    const container = this.shadowRoot.getElementById('pillContainer');
    if (container) {
      container.addEventListener('scroll', () => this.#updateIndicator(), { passive: true });
    }
  }

  async #fetchInitialData() {
    try {
      const [makesRes, enumsRes, countRes] = await Promise.all([
        fetch(`https://www.carify.com/public_api/vehicles/makes/?lang=${SITE_LOCALE}`, { headers: { "Accept-Language": SITE_LOCALE } }).then(r => r.json()).catch(() => []),
        fetch(`https://www.carify.com/public_api/vehicles/enums/?lang=${SITE_LOCALE}`, { headers: { "Accept-Language": SITE_LOCALE } }).then(r => r.json()).catch(() => ({})),
        fetch(`https://www.carify.com/public_api/vehicles/count/?lang=${SITE_LOCALE}`, { headers: { "Accept-Language": SITE_LOCALE } }).then(r => r.json()).catch(() => ({ total_count: 0 }))
      ]);

      const uppercaseBrands = ["BMW", "VW"];
      const brandOpts = {};
      const makesList = makesRes.results || []
      makesList.forEach(make => {
        const brand = make.name;
        const key = brand.toUpperCase().replace(/\s+/g, '-');
        const label = uppercaseBrands.includes(brand.toUpperCase())
          ? brand.toUpperCase()
          : brand.toLowerCase().split(/[\s-]/).map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
        brandOpts[key] = { label, extra: make.vector_image };
      });
      this.pills.make.options = brandOpts;

      const bodyOpts = {};
      const carTypes = enumsRes.results.car_type_options;
      Object.entries(carTypes).forEach(([k, v]) => { bodyOpts[k] = { label: v } });
      this.pills.body.options = bodyOpts;

      const gearOpts = {};
      const transOpts = enumsRes.results.transmission_options
      Object.entries(transOpts).slice(0, 2).forEach(([k, v]) => {
        gearOpts[k] = { label: v, extra: null };
      });
      this.pills.gear.options = gearOpts;

      const fuelOpts = {};
      const fOpts = enumsRes.results.fuel_type_options
      Object.entries(fOpts).slice(1, 4).forEach(([k, v]) => {
        fuelOpts[k] = { label: v, extra: null };
      });
      this.pills.fuel.options = fuelOpts;

      this.allCount = countRes.total_count || 0;
      this.totalCount = this.allCount;
      this.#updateButtonLabel(this.totalCount);
    } catch (err) {
      console.error('Failed to load search filter metadata', err);
    }
  }

  #renderOptions() {

    Object.keys(this.pills).forEach(key => {
      const gridEl = this.shadowRoot.getElementById(`grid-${key}`);
      if (!gridEl) return;
      gridEl.innerHTML = '';

      const pill = this.pills[key];

      const title = this.shadowRoot.querySelector(`[data-tab=${key}] .pill-title`)
      if (title) title.textContent = pill.title

      Object.entries(pill.options).forEach(([optKey, optVal]) => {
        const card = document.createElement('div');
        card.className = 'filter-card';
        if (pill.selected.has(optKey)) card.classList.add('selected');

        card.dataset.category = key;
        card.dataset.value = optKey;

        let contentHtml = '';
        if (key === 'make' && optVal.extra) {
          contentHtml += `<div class="brand-logo-wrap"><img src="${optVal.extra}" alt="${optVal.label}" loading="lazy"/></div>`;
        }
        contentHtml += `<span>${optVal.label}</span>`;
        // contentHtml += `<svg class="check-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>`;

        card.innerHTML = contentHtml;
        gridEl.appendChild(card);
      });
    });
  }

  #setupEventListeners() {
    const root = this.shadowRoot;
    const pillContainer = root.getElementById('pillContainer');
    const panelsContainer = root.getElementById('panelsContainer');

    root.querySelector('.closer').addEventListener('click', () => {
      this.#setActive('')
    })

    root.querySelector('.clear').addEventListener('click', () => {
      root.querySelectorAll('.filter-card').forEach(card => card.classList.remove('selected'));
      Object.values(this.pills).forEach(p => p.selected.clear())
      this.#updateButtonLabel(this.totalCount)
      this.#updateSubtitles()
      this.#updateIndicator()
      this.#setActive('')
      this.#triggerLiveSearch()
    })

    pillContainer.querySelectorAll('.pill-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const tab = btn.dataset.tab;
        this.#setActive(this.activeIndex === tab ? '' : tab);
      });
    });

    panelsContainer.addEventListener('click', (e) => {
      e.stopPropagation();
      const card = e.target.closest('.filter-card');
      if (!card) return;

      const category = card.dataset.category;
      const value = card.dataset.value;
      this.#toggleFilter(category, value);
    });

    window.addEventListener('click', (e) => {
      if (!this.contains(e.target)) {
        this.#setActive('');
      }
    });
  }

  async #setActive(index) {
    this.activeIndex = index;
    this.isOpen = index !== '';

    const panelsContainer = this.shadowRoot.getElementById('panelsContainer');
    if (this.isOpen) {
      panelsContainer.classList.add('open');
    } else {
      panelsContainer.classList.remove('open');
    }

    this.shadowRoot.querySelectorAll('.tab-panel').forEach(panel => {
      if (panel.dataset.panel === index) {
        panel.classList.add('active-panel');
      } else {
        panel.classList.remove('active-panel');
      }
    });

    this.shadowRoot.querySelectorAll('.pill-btn').forEach(btn => {
      if (btn.dataset.tab === index) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });

    this.#updateIndicator();
  }

  #updateIndicator() {
    const indicator = this.shadowRoot.getElementById('slidingIndicator');
    const container = this.shadowRoot.getElementById('pillContainer');
    const keys = Object.keys(this.pills);
    const index = keys.indexOf(this.activeIndex);

    if (index === -1 || !container) {
      indicator.style.opacity = '0';
      return;
    }

    const pillButtons = container.querySelectorAll('.pill-btn');
    const el = pillButtons[index];
    if (!el) {
      indicator.style.opacity = '0';
      return;
    }

    const containerRect = container.getBoundingClientRect();
    const elRect = el.getBoundingClientRect();

    indicator.style.opacity = '1';
    indicator.style.width = `${elRect.width}px`;
    // Include container.scrollLeft so the sliding indicator stays aligned during horizontal scroll
    indicator.style.transform = `translateX(${elRect.left - containerRect.left + container.scrollLeft}px)`;
  }

  #toggleFilter(category, valKey) {
    const pill = this.pills[category];
    if (!pill) return;

    if (pill.selected.has(valKey)) {
      pill.selected.delete(valKey);
    } else {
      if (!pill.multi) pill.selected.clear();
      pill.selected.set(valKey, pill.options[valKey]);
    }

    const grid = this.shadowRoot.getElementById(`grid-${category}`);
    grid.querySelectorAll('.filter-card').forEach(card => {
      const v = card.dataset.value;
      if (pill.selected.has(v)) {
        card.classList.add('selected');
      } else {
        card.classList.remove('selected');
      }
    });

    this.#updateSubtitles();
    this.#triggerLiveSearch();
  }

  #updateSubtitles() {
    Object.keys(this.pills).forEach(key => {
      const pill = this.pills[key];
      const subtitles = Array.from(pill.selected.keys())
        .map(k => pill.options[k]?.label)
        .filter(Boolean)
        .join(', ');

      const subEl = this.shadowRoot.getElementById(`sub-${key}`);
      const btnEl = this.shadowRoot.querySelector(`.pill-btn[data-tab="${key}"]`);
      if (subEl) subEl.textContent = subtitles;
      if (btnEl) {
        if (subtitles) btnEl.setAttribute('has-subtitle', '');
        else btnEl.removeAttribute('has-subtitle');
      }
    });
  }

  getFiltersState() {
    return {
      brands: Array.from(this.pills.make.selected.keys()),
      bodyTypes: Array.from(this.pills.body.selected.keys()),
      transmission: Array.from(this.pills.gear.selected.keys()),
      fuelTypes: Array.from(this.pills.fuel.selected.keys()),
      priceRange: Array.from(this.pills.price.selected.keys()),
      registrationYears: Array.from(this.pills.year.selected.keys()), // Added
    };
  }

  buildQueryString() {
    const params = new URLSearchParams();
    const filters = this.getFiltersState();

    if (filters.brands.length) params.append('makes', filters.brands.join(','));
    if (filters.bodyTypes.length) params.append('car_types', filters.bodyTypes.join(','));
    if (filters.transmission.length) params.append('transmissions', filters.transmission.join(','));
    if (filters.fuelTypes.length) params.append('fuel_types', filters.fuelTypes.join(','));
    if (filters.registrationYears.length) params.append('registration_years', filters.registrationYears.join(',')); // Added

    const priceKey = filters.priceRange[0];
    if (priceKey) {
      const ranges = { s: [200, 650], m: [651, 850], l: [200, 1000], b: [1001, 10000] };
      if (ranges[priceKey]) params.append('lease_package_price_range', ranges[priceKey].join(','));
    }

    return params.toString();
  }

  async #triggerLiveSearch() {
    const queryString = this.buildQueryString();

    this.dispatchEvent(new CustomEvent('filter:change', {
      detail: { filters: this.getFiltersState(), queryString },
      bubbles: true,
      composed: true
    }));
  }

  #updateButtonLabel(total) {
    const hasFilters = this.buildQueryString().length > 0;
    let label = `${total} ${$t('vehicles')}`

    if (this.isOpen && total <= 0) {
      label = `No results`
    } else if (hasFilters || total !== this.allCount) {
      label = `${total} ${$t('vehicles')}`;
    }
    const btnLabelEl = this.shadowRoot.getElementById('buttonLabel');
    const mobBtnLabelEl = this.shadowRoot.getElementById('mobileButtonLabel');

    if (btnLabelEl) btnLabelEl.textContent = label;
    if (mobBtnLabelEl) mobBtnLabelEl.textContent = label;
  }
}

customElements.define('vehicle-filter', VehicleFilter);
