import checkoutHtml from './checkout.html?raw';
import checkoutCss from './checkout.css?raw';
import { chfFormatter, getQueryValue, renderTranslations, SITE_LOCALE } from '@/utils';

const template = document.createElement('template');
template.innerHTML = `<style>${checkoutCss}</style>${checkoutHtml}`;

export class VehicleCheckout extends HTMLElement {
  #vehicle = {}
  #config = {}
  #options = {}
  #months = null;
  #leases = []
  #down_payment_adjustment_id = null;
  #lease_adjust = null;
  #km_adjust = null;
  #book_now = false;

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.appendChild(template.content.cloneNode(true));
  }

  connectedCallback() {

    renderTranslations(this.shadowRoot)
    this.#setupEventListeners();

    this.#down_payment_adjustment_id = getQueryValue("down_payment_adjustment_id")
    this.#lease_adjust = getQueryValue("lp_id")
    this.#km_adjust = getQueryValue("km_adjustment_id")

  }

  static get observedAttributes() {
    return ['vehicle_id', 'vehicle_slug', 'book', 'options', 'dp_adjustment_id', 'km_adjust', 'months_adjust'];
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'vehicle_id' && oldValue !== newValue) {
      this.#vehicle.id = newValue
    }
    if (name === 'vehicle_slug' && oldValue !== newValue) {
      this.#vehicle.slug = newValue
    }
    if (name === 'book' && oldValue !== newValue) {
      this.#book_now = newValue
    }
    if (name === 'options' && oldValue !== newValue) {
      try {
        this.render(JSON.parse(newValue));
      } catch (err) {
        console.error('Invalid JSON string passed to [vehicle] attribute:', err);
      }
    }
  }

  async render(leases) {
    // Set available package types for vehicle
    const packages = new Set(leases.flatMap(item => item.package_types));
    // For now, widgets do not support try & buy configuration.
    packages.delete('try_and_buy')

    // Set available lease options
    const duration = leases.map(lp => ({ id: lp.id, text: `${lp.duration_months}`, km_options: lp.km_options, months: lp.duration_months }))

    this.#leases = duration;

    this.#config.package = "fixed"
    this.#config.lease = this.#lease_adjust ?? this.#leases[0].id
    const d = duration.find(d => d.id === this.#config.lease)

    this.#months = d.months + ''

    this.#renderPackageOptions(packages)
    this.#renderLeaseOptions(duration);

    await this.#fetchAdjustments()
  }

  async #fetchAdjustments() {

    try {
      const response = await fetch(`https://www.carify.com/public_api/leases/adjustments/${this.#vehicle.id}/?lease_package_id=${this.#config.lease}`, {
        headers: { 'Content-Type': 'application/json' },
      });
      if (!response.ok) throw new Error(`HTTP error: ${response.status}`);
      const data = await response.json();

      const kms = data.results.filter(d => d.price_adjustment_type === "percentage")
      kms.push({ id: null, name: '1750 KM', km_adjustment: 0 })
      kms.sort((a, b) => a.km_adjustment - b.km_adjustment)

      this.#options.kilometers = kms

      // Set available insurance options for lease package
      const insurance = data.results.filter(d => {
        if (!d.is_insurance) return false
        const duration = d.duration_filter;
        if (!duration || duration.trim() === "") return true;
        return duration.split(",").map(v => v.trim()).includes(this.#months);
      });
      insurance.unshift({ id: null, name: 'BUDGET', duration_filter: "", is_insurance: true })

      this.#options.insurance = insurance


      // Set available down payment options for lease package
      const down = data.results.filter(d => d.price_adjustment_type === "down_payment");
      down.push({ id: null, down_payment: 0, monthly_extras: 0 })
      down.sort((a, b) => b.monthly_extras - a.monthly_extras)
      this.#options.down_payment = down

      // Reset selected values
      const activeKM = this.#options.kilometers.find(e => e.id === this.#config.kilometers)
      if (!activeKM) this.#config.kilometers = this.#options.kilometers[0].id

      const activeInsurance = this.#options.insurance.find(e => e.id === this.#config.insurance)
      if (!activeInsurance) this.#config.insurance = this.#options.insurance[0].id

      const activeDownPayment = this.#options.down_payment.find(e => e.id === this.#config.down)
      if (!activeDownPayment) {
        const activeDP = this.#options.down_payment.find(dp => dp.id === this.#down_payment_adjustment_id);
        if (activeDP) {
          this.#config.down = activeDP.id
        }
      }

    } catch (err) {
      console.error('Failed to fetch adjustments', err);
    }

    this.#renderKilometerOptions()
    this.#renderDownPaymentOptions()
    this.#renderInsuranceOptions()

    await this.#fetchQuote()
  }

  async #fetchQuote() {

    const adjustments = Object.values(this.#config).filter(Boolean).filter(v => !["fixed", "flex", "try_and_buy"].includes(v))

    const leaseID = this.#config.lease;

    const args = {
      "lease_package_id": leaseID,
      "adjustments": adjustments,
      "one_month_only": false
    }
    const params = new URLSearchParams(args).toString();
    try {
      const response = await fetch(`https://www.carify.com/public_api/leases/quote/?${params.toString()}`, {
        headers: { 'Content-Type': 'application/json' }
      });

      if (!response.ok) throw new Error(`HTTP error: ${response.status}`);
      const data = await response.json();
      this.#updatePricing(data.results)
    } catch (err) {
      console.error('Failed to update quote:', err);
    }

    // Update button URL
    const qp = { lp_id: leaseID, package_types: this.#config.package }
    if (this.#config.down) qp.down_payment_adjustment_id = this.#config.down

    // if (this.#config.kilometers) {
    const kk = this.#options.kilometers.find(k => k.id === this.#config.kilometers)
    // qp.km = 1750 + (kk.km_adjustment)
    qp.km_adjustment_id = kk?.id ?? ''
    // }

    const query = new URLSearchParams(qp).toString()
    const start = this.shadowRoot.querySelector('.btn-submit');

    const variant = this.#book_now ? "book_now" : "view"

    const url = `https://www.carify.com/${SITE_LOCALE}/${variant}/${this.#vehicle.slug}/${this.#vehicle.id}?${query.toString()}&adjustments_ids=${adjustments.join(',')}`
    start.setAttribute("href", url)

  }

  #setupEventListeners() {
    const pillContainers = this.shadowRoot.querySelectorAll('.pill-container');

    pillContainers.forEach((container) => {
      container.addEventListener('click', async (e) => {
        const target = e.target.closest('.pill');
        if (!target || target.classList.contains('active')) return;

        // Update active class state within group
        container.querySelectorAll('.pill').forEach((btn) => btn.classList.remove('active'));
        target.classList.add('active');

        // Identify group context and map state key
        // const group = target.closest('.option-group');
        // const titleText = group?.querySelector('.group-title')?.textContent.trim().toLowerCase() || '';
        // const selectedValue = target.textContent.trim();

        this.#config[target.dataset.adj] = target.dataset.id ?? null

        if (target.dataset.adj === "kilometers") {
          this.#km_adjust = target.dataset.id
        }
        if (target.dataset.adj === "down") {
          this.#down_payment_adjustment_id = target.dataset.id
        }

        if (container.classList.contains("packages")) {
          // let options = this.#product.lease_packages.map(lp => ({ data: lp.id, text: `${lp.duration_months}`, km_options: lp.km_options, months: lp.duration_months }))
          // if (target.dataset.id === "try_and_buy") {
          //   this.#renderLeaseOptions(options.filter(o => o.months <=6))
          //   this.#config.down = ""
          //   this.shadowRoot.querySelector('.down-group').style.display = 'none'
          // } else {
          //   this.#renderLeaseOptions(options)
          //   this.shadowRoot.querySelector('.down-group').style.display = 'block'
          // }
        }

        if (container.classList.contains("leases")) {
          this.#months = target.dataset.months
          if (parseInt(this.#months) <= 3) {
            this.#down_payment_adjustment_id = null
            this.#config.down = ""
            this.shadowRoot.querySelector('.down-group').style.display = 'none'
          } else {
            this.shadowRoot.querySelector('.down-group').style.display = 'block'
          }
        }

        const root = this.shadowRoot;
        root.querySelector('.loader').style.display = 'inline-block'
        root.querySelector('.price-monthly').style.display = 'none'

        if (container.dataset.trigger == "adjustments") {
          await this.#fetchAdjustments()
        } else if (container.dataset.trigger == "quote") {
          await this.#fetchQuote()
        }

        root.querySelector('.loader').style.display = 'none'
        root.querySelector('.price-monthly').style.display = 'block'
      });
    });
  }


  #renderPackageOptions(options) {
    const container = this.shadowRoot.querySelector('.pill-container.packages');
    if (!container) return;
    // Clear any existing static buttons from the HTML template
    container.innerHTML = '';
    for (const pkg of options) {
      const btn = document.createElement('button');
      // Set the first item as active by default, or match current state
      const isActive = pkg == "fixed"
      btn.className = `pill ${isActive ? 'active' : ''}`;
      btn.textContent = pkg.replace(/_/g, ' ').replace(/\b\w/g, char => char.toUpperCase()).replace("And", "&")
      // Store the unique lease ID on the element for easy retrieval
      btn.dataset.id = pkg
      btn.dataset.adj = "package";
      container.appendChild(btn);
    }
  }

  #renderLeaseOptions(options) {
    const container = this.shadowRoot.querySelector('.pill-container.leases');
    if (!container) return;
    container.innerHTML = '';
    options.forEach((lease, index) => {
      const btn = document.createElement('button');
      const isActive = lease.id === this.#lease_adjust || this.#config.lease === lease.id;
      if (isActive) {
        this.#months = lease.months + ''
      }

      btn.className = `pill ${isActive ? 'active' : ''}`;
      btn.textContent = lease.text;
      btn.dataset.id = lease.id;
      btn.dataset.adj = "lease";
      btn.dataset.months = lease.months;
      container.appendChild(btn);
    });
  }

  #renderKilometerOptions() {

    const container = this.shadowRoot.querySelector('.pill-container.kilometers');
    if (!container) return;
    // Clear any existing static buttons from the HTML template
    container.innerHTML = '';
    this.#options.kilometers.forEach((op, index) => {

      const btn = document.createElement('button');
      // // Set the first item as active by default, or match current state
      const isActive = this.#config.kilometers === op.id || op.id == this.#km_adjust
      // const isActive = op.id == this.#config.kilometers === op.id;
      btn.className = `pill ${isActive ? 'active' : ''}`;
      btn.textContent = `${op.name}`.replace("KM", "km")
      // // Store the unique lease ID on the element for easy retrieval
      btn.dataset.id = op.id ?? '';
      btn.dataset.adj = "kilometers";
      container.appendChild(btn);
    });
  }

  #renderInsuranceOptions() {
    const container = this.shadowRoot.querySelector('.pill-container.insurance');
    if (!container) return;

    // Clear any existing static buttons from the HTML template
    container.innerHTML = '';
    this.#options.insurance.forEach((op, index) => {
      const btn = document.createElement('button');
      // // Set the first item as active by default, or match current state
      // const isActive = index === 0;
      const isActive = this.#config.insurance === op.id;

      btn.className = `pill ${isActive ? 'active' : ''}`;
      btn.textContent = `${op.name}`
      // // Store the unique lease ID on the element for easy retrieval
      btn.dataset.id = op.id ?? '';
      btn.dataset.adj = "insurance";
      container.appendChild(btn);
    });
  }


  #renderDownPaymentOptions() {

    const container = this.shadowRoot.querySelector('.pill-container.down');
    if (!container) return;

    // Clear any existing static buttons from the HTML template
    container.innerHTML = '';
    this.#options.down_payment.forEach((op, index) => {

      const btn = document.createElement('button');
      // // Set the first item as active by default, or match current state
      const isActive = op.id === this.#down_payment_adjustment_id ?? this.#config.down === op.id;

      btn.className = `pill ${isActive ? 'active' : ''}`;
      btn.textContent = chfFormatter.format(op.down_payment);
      // // Store the unique lease ID on the element for easy retrieval
      btn.dataset.id = op.id ?? '';
      btn.dataset.adj = "down";
      container.appendChild(btn);
    });
  }

  #updatePricing(data) {

    const extraKm = this.shadowRoot.querySelector('.price-extra-km');
    const downPayment = this.shadowRoot.querySelector('.price-down-payment');
    const monthlyTotal = this.shadowRoot.querySelector('.price-monthly');
    // const dueNow = this.shadowRoot.querySelector('.price-due-now');

    if (extraKm) extraKm.textContent = `CHF ${data.km_overage_costs}`
    if (this.#config.down) {
      const d = this.#options.down_payment.find(i => i.id === this.#config.down)
      downPayment.textContent = chfFormatter.format(d.down_payment)
      downPayment.closest('div').classList.remove("hidden")
    } else {
      downPayment.closest('div').classList.add("hidden")
    }

    const price = this.shadowRoot.querySelector('.price-monthly');

    switch (this.#config.package) {
      case "fixed":
        price.textContent = chfFormatter.format(data.monthly_total_fixed);
        break;
      case "flex":
        price.textContent = chfFormatter.format(data.monthly_total);
        break;
      case "try_and_buy":
        price.textContent = chfFormatter.format(data.try_and_buy.end_price);
        break;
    }
  }
}

customElements.define('vehicle-checkout', VehicleCheckout);
