import templateHtml from './photos.html?raw';
import stylesCss from './photos.css?raw';

const template = document.createElement('template');
template.innerHTML = `<style>${stylesCss}</style>${templateHtml}`;

class VehiclePhotos extends HTMLElement {
  static get observedAttributes() {
    return ['images'];
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'images' && oldValue !== newValue) {
      this.render();
    }
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.appendChild(template.content.cloneNode(true));
  }

  connectedCallback() {
    this.render();
  }

  get imagesList() {
    try {
      const attr = this.getAttribute('images');
      return attr ? JSON.parse(attr) : [];
    } catch (e) {
      return [];
    }
  }

  render() {
    const images = this.imagesList;
    const root = this.shadowRoot;

    const mainImg = root.querySelector('.main-photo');
    const thumb1 = root.querySelector('.thumb-1');
    const thumb2 = root.querySelector('.thumb-2');
    const thumb3 = root.querySelector('.thumb-3');
    const thumb4 = root.querySelector('.thumb-4');

    const thumbnails = [thumb1, thumb2, thumb3, thumb4];

    if (mainImg) {
      mainImg.src = images[0] || '';
    }

    thumbnails.forEach((thumb, index) => {
      if (thumb) {
        const imgUrl = images[index + 1];
        if (imgUrl) {
          thumb.src = imgUrl;
          thumb.style.display = 'block';
        } else {
          thumb.style.display = 'none';
        }
      }
    });
  }
}

customElements.define('vehicle-photos', VehiclePhotos);
