import cardHtml from './card.html?raw';
import cardCss from './card.css?raw';
import { chfFormatter, renderTranslations, $t } from '@/utils.js';

const template = document.createElement('template');
template.innerHTML = `<style>${cardCss}</style>${cardHtml}`;

export class VehicleCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.appendChild(template.content.cloneNode(true));
  }

  static get observedAttributes() {
    return ['loading', 'name', 'image', 'price', 'url'];
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue !== newValue) {
      this.render();
    }
  }

  render() {

    const root = this.shadowRoot;
    renderTranslations(root)

    const cardEl = root.querySelector('.card');
    const imgEl = root.querySelector('.vehicle-img');
    const titleEl = root.querySelector('.vehicle-title');
    const priceEl = root.querySelector('.price-value');

    const isLoading = this.hasAttribute('loading');

    if (isLoading) {
      cardEl.classList.add('skeleton');
      cardEl.removeAttribute('href');
      titleEl.textContent = '';
      priceEl.textContent = '';
      imgEl.src = '';
      imgEl.alt = '';
      return;
    }

    cardEl.classList.remove('skeleton');
    const url = this.getAttribute('url');

    if (url) {
      cardEl.href = url;
      if (url.includes("carify.com")) {
        cardEl.setAttribute("target", "_blank")
      }
    } else {
      cardEl.removeAttribute('href');
    }

    const name = this.getAttribute('name');
    const image = this.getAttribute('image');
    const price = this.getAttribute('price');

    if (name) {
      titleEl.textContent = name;
      titleEl.title = name;
    }
    if (image) {
      imgEl.src = image;
      imgEl.alt = name || 'Vehicle';
    } else {
      imgEl.src = 'https://via.placeholder.com/300x150?text=Vehicle';
    }

    if (price) {
      let priceValue = Number(price);
      priceEl.textContent = `${chfFormatter.format(priceValue)}/${$t('month')}`;
    }
  }
}

customElements.define('vehicle-card', VehicleCard);
