import templateHtml from './catalog.html?raw';
import stylesCss from './catalog.css?raw';
import themeCss from '@/external/theme.css?raw';

import '@/internal/filter/filter.js';
import '@/internal/card/card.js';
import { generateURL, renderTranslations, SITE_ID } from '@/utils.js';

const template = document.createElement('template');
template.innerHTML = `<style>${themeCss}${stylesCss}</style>${templateHtml}`;

export class VehicleCatalog extends HTMLElement {
  #refs = []

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.appendChild(template.content.cloneNode(true));

    this.total = 0;
    this.cardURL = this.getAttribute('target') || null;

    const limit = this.getAttribute('limit') || '8';

    this.query = new URLSearchParams({
      minimal: 'true',
      order_by: '-top_picks',
      apply_down_payment: 'true',
      limit: limit,
      offset: '0',
      dealer_id: SITE_ID
    });
  }

  connectedCallback() {
    const root = this.shadowRoot
    renderTranslations(root)

    this.#refs = {
      filter: root.querySelector("vehicle-filter"),
      catalog: root.querySelector('#catalog'),
      pagination: root.querySelector('#pagination'),
      pageIndicator: root.querySelector('#page-indicator'),
      first: root.querySelector('[data-action="first"]'),
      prev: root.querySelector('[data-action="prev"]'),
      next: root.querySelector('[data-action="next"]'),
      last: root.querySelector('[data-action="last"]'),
      noResults: root.querySelector('#no-results'),
    }

    this.#setupEventListeners();
    this.#renderControls();
    this.#fetchVehicles();
  }

  #renderControls() {
    if (this.#refs.filter) {
      this.#refs.filter.style.display = this.hasAttribute('filter') ? 'block' : 'none';
    }
  }

  #scrollToCatalog() {
    // const catalogContainer = this.shadowRoot.querySelector('#catalog');
    const catalogContainer = this;
    if (catalogContainer) {
      const yOffset = -10;
      const y = catalogContainer.getBoundingClientRect().top + window.pageYOffset + yOffset;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
  }

  async #fetchVehicles() {

    const catalogContainer = this.#refs.catalog
    const noResultsEl = this.#refs.noResults
    const limit = parseInt(this.query.get('limit')) || 8;

    noResultsEl.style.display = 'none';
    this.#refs.pagination.style.display = 'none';

    let cards = Array.from(catalogContainer.querySelectorAll('vehicle-card'));
    if (cards.length !== limit) {
      catalogContainer.innerHTML = '';
      cards = [];
      for (let i = 0; i < limit; i++) {
        const card = document.createElement('vehicle-card');
        catalogContainer.appendChild(card);
        cards.push(card);
      }
    }

    cards.forEach(card => {
      card.style.display = 'block';
      card.setAttribute('loading', '');
      card.removeAttribute('name');
      card.removeAttribute('image');
      card.removeAttribute('price');
    });

    try {
      const url = `https://www.carify.com/public_api/vehicles/?${this.query.toString()}`;
      const response = await fetch(url);
      if (!response.ok) throw new Error('Failed to fetch data');

      const data = await response.json();
      const vehicles = Array.isArray(data) ? data : (data.results || []);

      this.total = typeof data.total_count === 'number' ? data.total_count : vehicles.length;
      if (this.#refs.filter) this.#refs.filter.setAttribute("total", this.total)

      if (vehicles.length === 0) {
        cards.forEach(card => card.style.display = 'none');
        noResultsEl.style.display = 'block';
        this.#updatePaginationControls(0, limit);
        this.#refs.filter.setAttribute("total", 0)
        return;
      }

      cards.forEach((card, index) => {
        const vehicle = vehicles[index];
        if (vehicle) {
          card.style.display = 'block';
          card.removeAttribute('loading');
          card.setAttribute('name', vehicle.name || '');
          card.setAttribute('image', vehicle.profile_picture || '');
          card.setAttribute('price', vehicle.min_price_package.km_option.monthly_total_fixed);
          card.setAttribute('url', generateURL(vehicle.slug, vehicle.id, vehicle.down_payment.adj_id, vehicle.min_price_package, this.cardURL));
        } else {
          card.style.display = 'none';
        }
      });

      this.#updatePaginationControls(this.total, limit);

    } catch (error) {
      console.error(error);
      catalogContainer.innerHTML = `<p class="error">Could not load vehicle catalog.</p>`;
    }
  }

  #setupEventListeners() {
    this.shadowRoot.addEventListener('filter:change', (e) => {
      const { filters, queryString } = e.detail;

      // Clear out old filter parameters first so deselected ones don't linger
      this.query.delete('makes');
      this.query.delete('car_types');
      this.query.delete('transmissions');
      this.query.delete('fuel_types');

      if (queryString) {
        const params = new URLSearchParams(queryString);
        for (const [key, val] of params.entries()) {
          this.query.set(key, val);
        }
      }
      // Reset offset and fetch
      this.query.set('offset', '0');
      // this.scrollToCatalog();
      this.#fetchVehicles();
    });

    this.#refs.pagination.addEventListener('click', (e) => {
      const button = e.target.closest('.page-btn[data-action]');
      if (!button || button.disabled) return;

      const action = button.dataset.action;
      const limit = parseInt(this.query.get('limit')) || 8;
      const offset = parseInt(this.query.get('offset')) || 0;
      const totalPages = Math.ceil(this.total / limit) || 1;

      switch (action) {
        case 'first':
          this.query.set('offset', '0');
          break;
        case 'prev':
          this.query.set('offset', Math.max(0, offset - limit));
          break;
        case 'next':
          if (offset + limit < this.total) {
            this.query.set('offset', offset + limit);
          }
          break;
        case 'last':
          const lastOffset = (totalPages - 1) * limit;
          this.query.set('offset', Math.max(0, lastOffset));
          break;
      }

      this.#scrollToCatalog();
      this.#fetchVehicles();
    });
  }

  #updatePaginationControls(total, limit) {
    const offset = parseInt(this.query.get('offset')) || 0;
    const currentPage = Math.floor(offset / limit) + 1;
    const totalPages = Math.ceil(total / limit) || 1;

    if (this.#refs.pageIndicator) {
      this.#refs.pageIndicator.textContent = currentPage;
    }
    // If total results fit on a single page (or 0 results), disable pagination buttons or hide pagination
    const noPaginationNeeded = total <= limit;
    const shouldDisablePrev = noPaginationNeeded || currentPage === 1;
    const shouldDisableNext = noPaginationNeeded || currentPage >= totalPages;

    // Apply native disabled state AND the '.disabled' CSS class to match your markup
    const applyState = (btn, isDisabled) => {
      if (!btn) return;
      btn.disabled = isDisabled;
      if (isDisabled) {
        btn.classList.add('disabled');
      } else {
        btn.classList.remove('disabled');
      }
    };

    applyState(this.#refs.first, shouldDisablePrev);
    applyState(this.#refs.prev, shouldDisablePrev);
    applyState(this.#refs.next, shouldDisableNext);
    applyState(this.#refs.last, shouldDisableNext);

    this.#refs.pagination.style.display = total <= limit ? 'none' : 'flex';
  }
}

customElements.define('carify-vehicle-catalog', VehicleCatalog);
