import { dictionary } from "@/locale/translations.js";

function getSiteIdFromScript() {
  const scripts = document.querySelectorAll('script');
  for (const script of scripts) {
    const src = script.getAttribute('src');
    // Match part of your built bundle or script name
    if (src && (src.includes('carify-components')) || src.includes('index')) {
      try {
        const url = new URL(src, window.location.href);
        const id = url.searchParams.get('id');
        if (id) return id;
      } catch (e) {
        // Invalid URL structure, ignore and continue
      }
    }
  }
  // Dev mode fallback
  const params = new URLSearchParams(window.location.search);
  if (params.has('id')) {
    return params.get('id');
  }
  return ''
}

function getSiteLocale() {
  const supportedLocales = ['en', 'de', 'fr', 'it'];
  const browserLocale = document.documentElement.lang.split('-')[0].toLowerCase();

  return supportedLocales.includes(browserLocale) ? browserLocale : 'de';
}

export const SITE_ID = getSiteIdFromScript();
export const SITE_LOCALE = getSiteLocale()

export const getQueryValue = (key) => {
  const urlParams = new URLSearchParams(window.location.search);
  return urlParams.get(key);
}

export const generateURL = (slug, id, adj, mins, page) => {
  if (page) {
    return `${page}?uuid=${id}&down_payment_adjustment_id=${adj}&lp_id=${mins.id}&km_adjustment_id=${mins.km_option.id}`
  }
  return `https://www.carify.com/${SITE_LOCALE}/view/${slug}/${id}?down_payment_adjustment_id=${adj}`

}

export const renderTranslations = (root) => {
  const translations = root.querySelectorAll('[data-t]');
  translations.forEach(e => {
    e.textContent = $t(e.dataset.t)
  })
}

export const getOdometerRange = (orig_odometer) => {
  const orig_odo = orig_odometer || null
  if (orig_odo) {
    const rounded = Math.floor(orig_odo / 5000) * 5000
    let min = rounded;
    let max = rounded + 10000;
    return `${min.toLocaleString('de').replace('.', "'")}-${max.toLocaleString('de').replace('.', "'")} km`
  }
  return ''
}

export const $t = (key, count = 1) => {
  const translation = dictionary[SITE_LOCALE]?.[key] ?? dictionary.en?.[key] ?? key;
  if (typeof translation === 'object') {
    const pluralForm = new Intl.PluralRules(SITE_LOCALE).select(count);
    return translation[pluralForm] ?? translation.other ?? key;
  }
  return translation;
};

export const chfFormatter = new Intl.NumberFormat('de-CH', {
  style: 'currency',
  currency: 'CHF',
  minimumFractionDigits: 0,
  maximumFractionDigits: 0
});
